from datetime import date
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
from cryptography.hazmat.primitives.serialization import Encoding, PrivateFormat, NoEncryption


def sign_with_timestamp(data: bytes, key: bytes) -> bytes:
    private_key = Ed25519PrivateKey.from_private_bytes(key)
    payload = data + date.today().isoformat().encode()
    return private_key.sign(payload)


# --- Tester ---
import unittest
from unittest.mock import patch


class TestSignWithTimestamp(unittest.TestCase):
    def setUp(self):
        self.private_key = Ed25519PrivateKey.generate()
        self.raw_key = self.private_key.private_bytes(
            Encoding.Raw, PrivateFormat.Raw, NoEncryption()
        )

    @patch("__main__.date")
    def test_signs_data_with_todays_date(self, mock_date):
        mock_date.today.return_value = date(2027, 10, 7)

        signature = sign_with_timestamp(b"hemligt meddelande", self.raw_key)

        # Verifiera att signaturen gäller för data + "2027-10-07"
        self.private_key.public_key().verify(
            signature, b"hemligt meddelande" + b"2027-10-07"
        )

    @patch("__main__.date")
    def test_signature_fails_for_wrong_date(self, mock_date):
        mock_date.today.return_value = date(2027, 10, 7)

        signature = sign_with_timestamp(b"data", self.raw_key)

        with self.assertRaises(Exception):
            self.private_key.public_key().verify(signature, b"data" + b"2027-10-08")


if __name__ == "__main__":
    unittest.main()
